INSERT INTO "MaturityCriterio" (id, "itemId", paso, "nombrePaso", "textoEn", "textoEs", "createdAt") VALUES
  ('mc-1.1-1', 'mi-1.1', 1, 'Defined', 'Is the Group Health and Safety Charter present on site?', '¿Está presente la Carta de Salud y Seguridad del Grupo en el lugar?', now()),
  ('mc-1.1-2', 'mi-1.1', 2, 'Developed', 'Is this the latest version of the Group Health and Safety Charter?', '¿Es esta la última versión de la Carta de Salud y Seguridad del Grupo?', now()),
  ('mc-1.1-3', 'mi-1.1', 3, 'Installed', 'Is the Group Health and Safety Charter content being communicated to all staff including newcomers (induction program)?', '¿Se comunica el contenido de la Carta de Salud y Seguridad del Grupo a todo el personal, incluidos los recién llegados (programa de inducción)?', now()),
  ('mc-1.1-4', 'mi-1.1', 4, 'Mastered', 'Are commitment, accountability and participation well defined in roles and responsibilities?', '¿Están bien definidos el compromiso, la rendición de cuentas y la participación en los roles y responsabilidades?', now()),
  ('mc-1.1-5', 'mi-1.1', 5, 'Sustained', 'Is there a process in place to regularly review if the latest version is being used and changes are communicated?', '¿Existe algún proceso para revisar regularmente si se está usando la última versión y se comunican los cambios?', now()),
  ('mc-1.2-1', 'mi-1.2', 1, 'Defined', 'Are Roles and Responsibilities (tasks) identified on site and defined in accordance with the Group procedure?', '¿Se identifican los roles y responsabilidades (tareas) en el lugar y se definen de acuerdo con el procedimiento del Grupo?', now()),
  ('mc-1.2-2', 'mi-1.2', 2, 'Developed', 'The Roles and responsibilities are also indicating the competence level needed for each role?', '¿Los roles y responsabilidades también indican el nivel de competencia necesario para cada puesto?', now()),
  ('mc-1.2-3', 'mi-1.2', 3, 'Installed', 'Is a detailed Responsible, Accountable, Consulted and Informed (RACI) table with persons identified for each task that is done?', '¿Existe una tabla detallada de Responsables, Responsables, Consultados e Informados (RACI) con personas identificadas para cada tarea realizada?', now()),
  ('mc-1.2-4', 'mi-1.2', 4, 'Mastered', 'Is this detailed table RACI communicated and implemented?', '¿Esta tabla detallada se comunica e implementa con ARC?', now()),
  ('mc-1.2-5', 'mi-1.2', 5, 'Sustained', 'Is there a process in place to regularly review, validate and modify the RACI and Roles and Responsibilities table?', '¿Existe algún proceso para revisar, validar y modificar regularmente la tabla RACI y de Roles y Responsabilidades?', now()),
  ('mc-1.3-1', 'mi-1.3', 1, 'Defined', 'RA procedure is defined in accordance with the group procedure.', 'El procedimiento de AR se define de acuerdo con el procedimiento de grupo.', now()),
  ('mc-1.3-2', 'mi-1.3', 2, 'Developed', 'Templates for Safety Plan, Safety in design register, RAMS, DTHA, LMRA have been developed and their use is understood by relevant personnel trhough training and on the job coaching. Also the procedure has been communicated to all staff.', 'Se han desarrollado plantillas para el Plan de Seguridad, el registro de seguridad en diseño, RAMS, DTHA, LMRA, y su uso es comprendido por el personal relevante a través de la formación y la formación en el puesto de trabajo. Además, el procedimiento ha sido comunicado a todo el personal.', now()),
  ('mc-1.3-3', 'mi-1.3', 3, 'Installed', 'Rigorous and comprehensive Risk Analysis are carried out to idenitfy hazards, risks and implement proper controls to mitigate the risks to an acceptable level.', 'Se realiza un análisis de riesgos riguroso y exhaustivo para identificar peligros, riesgos e implementar controles adecuados que mitiguen los riesgos hasta un nivel aceptable.', now()),
  ('mc-1.3-4', 'mi-1.3', 4, 'Mastered', 'Controls are implemented in accordance with the RA and continuous identification of hazards together with management of changes are in place to monitor and keep the risks to an acceptable level.', 'Los controles se implementan de acuerdo con la RA y se implementan la identificación continua de los peligros junto con la gestión de los cambios para monitorizar y mantener los riesgos en un nivel aceptable.', now()),
  ('mc-1.3-5', 'mi-1.3', 5, 'Sustained', 'A process is in place to regularly review, validate and modify the Risk Assessments on all differen levels, i.e. in the Safety Plan, Safety in design register, RAMS and DTHA.', 'Existe un proceso para revisar, validar y modificar regularmente las Evaluaciones de Riesgos en todos los diferentes niveles, es decir, en el Plan de Seguridad, el registro de Seguridad en el diseño, RAMS y DTHA.', now()),
  ('mc-1.4-1', 'mi-1.4', 1, 'Defined', 'Reporting, incident notification and investigation procedure is defined in accordance with the group procedure.', 'El procedimiento de informe, notificación de incidentes e investigación se define conforme al procedimiento del grupo.', now()),
  ('mc-1.4-2', 'mi-1.4', 2, 'Developed', 'The procedure including flow chart has been communicated and understood by all staff.', 'El procedimiento, incluido el diagrama de flujo, ha sido comunicado y comprendido por todo el personal.', now()),
  ('mc-1.4-3', 'mi-1.4', 3, 'Installed', 'The procedure is coming to life and us being used, meaning that there is a reporting system in place, all staff can report incidentand accidents, the system notifies the right people within the stated time period, identifies actions, installs teams to do the investigations, etc. Staff are also trained and instructed how to use the system.', 'El procedimiento está cobrando vida y estamos siendo utilizados, lo que significa que hay un sistema de informe, todo el personal puede informar de incidentes y accidentes, el sistema notifica a las personas adecuadas dentro del plazo establecido, identifica acciones, instala equipos para realizar las investigaciones, etc. El personal también recibe formación e instrucción sobre cómo usar el sistema.', now()),
  ('mc-1.4-4', 'mi-1.4', 4, 'Mastered', 'Reportings are done, people notified, investigations taken place, root causes and appropriate actions identified and completed. Monitoring of progress is taken place and sufficient resources provided to complete the open actions and learn the lessons.', 'Se realizan informes, se notifica a la gente, se llevan a cabo investigaciones, se identifican y completan las causas raíz y las acciones adecuadas. Se realiza un seguimiento del progreso y se proporcionan recursos suficientes para completar las acciones abiertas y aprender las lecciones.', now()),
  ('mc-1.4-5', 'mi-1.4', 5, 'Sustained', 'Also a process is in place to review, validate and modify the reporting, incident  notification and investigation system to further improve in accordance with the group procedure.', 'También existe un proceso para revisar, validar y modificar el sistema de informe, notificación de incidentes e investigación para mejorar aún más conforme al procedimiento del grupo.', now()),
  ('mc-1.5-1', 'mi-1.5', 1, 'Defined', 'Compliance assurance procedure is defined in accordance with the group procedure.', 'El procedimiento de garantía de cumplimiento se define de acuerdo con el procedimiento del grupo.', now()),
  ('mc-1.5-2', 'mi-1.5', 2, 'Developed', 'The procedure inlcuding templates for e.g. risk registers has been communicated and understood by relevant staff.', 'El procedimiento que incluye las plantillas para, por ejemplo, registros de riesgo, ha sido comunicado y comprendido por el personal relevante.', now()),
  ('mc-1.5-3', 'mi-1.5', 3, 'Installed', 'Compliance Risk registers have been completed that indicate how and to what level requirements are implemented. These requirements are coming from local legislation, Puratos group requirements, certification requirements and customer requirements.', 'Se han completado registros de Riesgos de Cumplimiento que indican cómo y a qué nivel se implementan los requisitos. Estos requisitos provienen de la legislación local, los requisitos del grupo Puratos, los requisitos de certificación y los requisitos del cliente.', now()),
  ('mc-1.5-4', 'mi-1.5', 4, 'Mastered', 'Actions are put in place immediately to close possible gaps with the requirements that need to be in place.', 'Se ponen en marcha de inmediato para cerrar posibles brechas en los requisitos que deben establecerse.', now()),
  ('mc-1.5-5', 'mi-1.5', 5, 'Sustained', 'There is a process in place to regularly review, validate and modify the compliance risk registers in accordance with the latest requirements. On top of this are regularly audits,  inspections undertaken to verify if the process in place is working properly.', 'Existe un proceso para revisar, validar y modificar regularmente los registros de riesgos de cumplimiento conforme a los últimos requisitos. Además de esto se realizan auditorías y inspecciones periódicas para verificar si el proceso en marcha funciona correctamente.', now()),
  ('mc-1.6-1', 'mi-1.6', 1, 'Defined', 'Necessary Safety Training with skills and competency matrix has been defined in accordance with the group procedure.', 'La formación necesaria en seguridad con la matriz de habilidades y competencias se ha definido de acuerdo con el procedimiento grupal.', now()),
  ('mc-1.6-2', 'mi-1.6', 2, 'Developed', 'The procedure including the matrix is developed and understood by all relevant personnel.', 'El procedimiento, incluyendo la matriz, es desarrollado y comprendido por todo el personal relevante.', now()),
  ('mc-1.6-3', 'mi-1.6', 3, 'Installed', 'The necessary trainings have been created and people assigned to follow them in accordinance with the skill and competency matrix.', 'Se han creado las formaciones necesarias y se les ha asignado a personas para seguirlas de acuerdo con la matriz de habilidades y competencias.', now()),
  ('mc-1.6-4', 'mi-1.6', 4, 'Mastered', 'Active monitoring is in place to make sure that all people needed the right training have received this, going from induction, basic  training, expert training to refresher training.', 'Existe una monitorización activa para asegurarse de que todas las personas que necesitan la formación adecuada han recibido esto, desde la inducción, la formación básica, la formación experta hasta la formación de actualización.', now()),
  ('mc-1.6-5', 'mi-1.6', 5, 'Sustained', 'A process is in place to regularly review, validate, and modify the safety training process including skills and competency matrix with training needs.', 'Existe un proceso para revisar, validar y modificar periódicamente el proceso de formación en seguridad, incluyendo la matriz de habilidades y competencias según las necesidades de formación.', now()),
  ('mc-1.7-1', 'mi-1.7', 1, 'Defined', 'Contractor management procedure has been defined in accordance with the group procedure.', 'El procedimiento de gestión del contratista se ha definido de acuerdo con el procedimiento grupal.', now()),
  ('mc-1.7-2', 'mi-1.7', 2, 'Developed', 'The procedure including the templates are developted and understood by all relevant personnel', 'El procedimiento, incluyendo las plantillas, es desarrollado y comprendido por todo el personal relevante', now()),
  ('mc-1.7-3', 'mi-1.7', 3, 'Installed', 'Contractors are selected and managed using evaluation of asked documentation, received risk assessments, H&S competences and training, on-site supervision, evaluation afterwards and creating lessons learned.', 'Los contratistas son seleccionados y gestionados mediante la evaluación de la documentación solicitada, evaluaciones de riesgos recibidas, competencias y formación en Ciencias y Ciencia, supervisión in situ, evaluación posterior y creación de lecciones aprendidas.', now()),
  ('mc-1.7-4', 'mi-1.7', 4, 'Mastered', 'The process is in place and a repository with the necessary documentation and evaluations are supporting the contractor management.', 'El proceso está en marcha y un repositorio con la documentación y evaluaciones necesarias apoya a la gestión del contratista.', now()),
  ('mc-1.7-5', 'mi-1.7', 5, 'Sustained', 'A process is in place to regularly review, validate and approve the contractors that can be used for activities on our sites.', 'Existe un proceso para revisar, validar y aprobar regularmente a los contratistas que pueden utilizarse para actividades en nuestros sitios.', now()),
  ('mc-1.8-1', 'mi-1.8', 1, 'Defined', 'When Root cause analysis and mitigation method requires change on the assets, a CapEx request is introduced with the relevant information to assess the project Proof of Value.', 'Cuando el análisis de causa raíz y el método de mitigación requieren cambios en los activos, se introduce una solicitud de CapEx con la información relevante para evaluar la Prueba de Valor del proyecto.', now()),
  ('mc-1.8-2', 'mi-1.8', 2, 'Developed', 'The procedure including the templates are developted and understood by all relevant personnel', 'El procedimiento, incluyendo las plantillas, es desarrollado y comprendido por todo el personal relevante', now()),
  ('mc-1.8-3', 'mi-1.8', 3, 'Installed', 'CAPEX is planned and prioritised based on Severity - Risk and miigation of the risk. Major CapEx projects have clear safety objectives and include safety deliverables in the project planning', 'El CAPEX se planifica y prioriza en función de la Gravedad - Riesgo y la modificación del riesgo. Los grandes proyectos de CapEx tienen objetivos claros de seguridad e incluyen entregables de seguridad en la planificación del proyecto', now()),
  ('mc-1.8-4', 'mi-1.8', 4, 'Mastered', 'CAPEX is timely asked for and planned multi-year to improve H&S in projects and to exclude root causes from incidents.', 'Se solicita y planifica oportunamente el CAPEX a un plazo plurianual para mejorar la salud y la ciencia en proyectos y excluir las causas raíz de los incidentes.', now()),
  ('mc-1.8-5', 'mi-1.8', 5, 'Sustained', 'A process is in place to plan and control the portfolio of safety CAPEX to enable the implementation of the Health and Safety vision of success.  All CapEx projects are controlled on the means in place to ensure safety in new CapEx.', 'Existe un proceso para planificar y controlar la cartera de CAPEX en seguridad que permita la implementación de la visión de éxito en Salud y Seguridad. Todos los proyectos de CapEx se controlan según los medios existentes para garantizar la seguridad en los nuevos CapEx.', now()),
  ('mc-2.1-1', 'mi-2.1', 1, 'Defined', 'LMRA is defined in accordance with the group procedure of Risk Assessment (see above).', 'La LMRA se define de acuerdo con el procedimiento grupal de Evaluación de Riesgos (véase arriba).', now()),
  ('mc-2.1-2', 'mi-2.1', 2, 'Developed', 'Questions to be used during LMRA have been developed and their use is understood by relevant personnel trhough training and on the job coaching. Also the procedure has been communicated to all staff.', 'Se han desarrollado preguntas que se deben utilizar durante la LMRA y su uso es comprendido por el personal relevante a través de la formación y la formación en el puesto de trabajo. Además, el procedimiento ha sido comunicado a todo el personal.', now()),
  ('mc-2.1-3', 'mi-2.1', 3, 'Installed', 'Last Minute Risk Assessments are used before starting a new task. Basically the operator of the task is asking himself the questions before starting the job safely.', 'Se utilizan evaluaciones de riesgo de última hora antes de comenzar una nueva tarea. Básicamente, el operador de la tarea se hace las preguntas antes de comenzar el trabajo con seguridad.', now()),
  ('mc-2.1-4', 'mi-2.1', 4, 'Mastered', 'The LMRA is being used for all tasks and a common mental process in all activities.', 'La LMRA se utiliza para todas las tareas y es un proceso mental común en todas las actividades.', now()),
  ('mc-2.1-5', 'mi-2.1', 5, 'Sustained', 'A process is in place to regularly review, validate and modify the LMRA process to further improve.', 'Existe un proceso para revisar, validar y modificar regularmente el proceso LMRA y así mejorarlo aún más.', now()),
  ('mc-2.2-1', 'mi-2.2', 1, 'Defined', 'HSE key performance indicators are defined in accordance with the incident prevention model (see H&S manual procedure)', 'Los indicadores clave de rendimiento de HSE se definen de acuerdo con el modelo de prevención de incidentes (véase el procedimiento manual de H&S)', now()),
  ('mc-2.2-2', 'mi-2.2', 2, 'Developed', 'The decision is made e.g. which leading indicators will be used and targets set to monitor continuous improvement.', 'Se toma la decisión, por ejemplo, qué indicadores adelantados se utilizarán y qué objetivos se establecen para monitorizar la mejora continua.', now()),
  ('mc-2.2-3', 'mi-2.2', 3, 'Installed', 'These targets and indicators are understood, communicated and monitored across the business.', 'Estos objetivos e indicadores se comprenden, comunican y supervisan en toda la empresa.', now()),
  ('mc-2.2-4', 'mi-2.2', 4, 'Mastered', 'Monthly progress against the indicators is monitored and actions are taken to meet the targets.', 'Se supervisa el progreso mensual respecto a los indicadores y se toman medidas para alcanzar los objetivos.', now()),
  ('mc-2.2-5', 'mi-2.2', 5, 'Sustained', 'Targets are met and new more stringent targets can be defined to further improve and become world class including comparing with benchmark data.', 'Se cumplen los objetivos y se pueden definir nuevas metas más estrictas para mejorar aún más y alcanzar la clase mundial, incluyendo la comparación con datos de referencia.', now()),
  ('mc-2.3-1', 'mi-2.3', 1, 'Defined', 'BBS monitoring and Safety Gemba walks are defined and described into the Compliance assurance procedure in accordance with the group procedure.', 'La monitorización del BBS y las caminatas de seguridad Gemba están definidas y descritas en el procedimiento de aseguramiento de cumplimiento conforme al procedimiento del grupo.', now()),
  ('mc-2.3-2', 'mi-2.3', 2, 'Developed', 'The principle and templates/checklist for doing the BBS monitoring and Safety Gemba Walk has been communicated and understood by relevant staff.', 'El principio y las plantillas/lista de verificación para realizar la Caminata de Gemba de Seguridad y el seguimiento del BBS han sido comunicados y comprendidos por el personal relevante.', now()),
  ('mc-2.3-3', 'mi-2.3', 3, 'Installed', 'The Checklists and templates are being used to complete the BBS monitoring and Safety Gemba walks.', 'Las listas de verificación y plantillas se están utilizando para completar las caminatas de monitorización BBS y Safety Gemba.', now()),
  ('mc-2.3-4', 'mi-2.3', 4, 'Mastered', 'Actions are put in place immediately to close possible gaps with the expected behaviours or requirements that need to be in place.', 'Se ponen en marcha acciones de inmediato para cerrar posibles carencias con los comportamientos o requisitos esperados que deben establecerse.', now()),
  ('mc-2.3-5', 'mi-2.3', 5, 'Sustained', 'There is a process in place to regularly review, validate and modify the processes/behaviours in accordance with the latest requirements.', 'Existe un proceso para revisar, validar y modificar regularmente los procesos/comportamientos de acuerdo con los requisitos más recientes.', now()),
  ('mc-2.4-1', 'mi-2.4', 1, 'Defined', 'Root cause analysis has been defined using the why tree method and part of the Reporting, incident notification and investigation procedure defined above.', 'El análisis de causa raíz se ha definido utilizando el método del árbol por qué y parte del procedimiento de Informe, notificación de incidentes e investigación descrito anteriormente.', now()),
  ('mc-2.4-2', 'mi-2.4', 2, 'Developed', 'The guidelines including templates on decision trees, flow charts, root cause alignment template were communicated and people were trained on how to best use it.', 'Se comunicaron las directrices, incluyendo plantillas sobre árboles de decisión, diagramas de flujo y plantilla de alineación de causas raíz, y se formó a la gente sobre cómo utilizarla mejor.', now()),
  ('mc-2.4-3', 'mi-2.4', 3, 'Installed', 'Investigations of Potential Serious Incidents are done and reports generated and placed in a central repository.', 'Se realizan investigaciones sobre posibles incidentes graves y se generan informes que se depositan en un repositorio central.', now()),
  ('mc-2.4-4', 'mi-2.4', 4, 'Mastered', 'Root causes are being used to define corrective actions and to avoid re-currence on the particular site.', 'Las causas raíz se están utilizando para definir acciones correctivas y evitar que se repitan en el sitio concreto.', now()),
  ('mc-2.4-5', 'mi-2.4', 5, 'Sustained', 'Re-currence of root causes is prevented due to improved awareness and sharing through e.g PoSI Safety Moments across the company (Group).', 'La recaída de las causas raíz se evita gracias a una mayor concienciación y compartición a través de PoSI Safety Moments en toda la empresa (Grupo).', now()),
  ('mc-2.5-1', 'mi-2.5', 1, 'Defined', 'Basics for creating and applying Safety moments has been defined in accordance with Group guidelines', 'Los conceptos básicos para crear y aplicar los momentos de seguridad se han definido de acuerdo con las directrices del Grupo', now()),
  ('mc-2.5-2', 'mi-2.5', 2, 'Developed', 'Templates for Safety moment is available and staff are being informed and instructed about this.', 'Hay plantillas para Safety Moment disponibles y el personal está siendo informado e instruido al respecto.', now()),
  ('mc-2.5-3', 'mi-2.5', 3, 'Installed', 'Safety moments are implemented at start of all meetings in accordance with Group guidelines', 'Los momentos de seguridad se implementan al inicio de todas las reuniones de acuerdo con las directrices del Grupo', now()),
  ('mc-2.5-4', 'mi-2.5', 4, 'Mastered', 'Safety moment are created, reviewed and added to the group repository', 'Se crean, revisan y se añaden al repositorio del grupo', now()),
  ('mc-2.5-5', 'mi-2.5', 5, 'Sustained', 'A culture of using safety moments in every meeting is present and staff are embracing the concept', 'Existe una cultura de aprovechar momentos de seguridad en cada reunión y el personal está adoptando el concepto', now()),
  ('mc-3.1-1', 'mi-3.1', 1, 'Defined', 'It is clearly what data has to be looked at, e.g. the incident pyramid (H.W. Heinrich) and at what interval this data has to be refreshed.  (weekly/monthly/season/yearly, etc.). Furthermore the root causes are known and statistics can be done on them.', 'Está claro qué datos deben analizarse, por ejemplo, la pirámide incidente (H.W. Heinrich) y en qué intervalo deben actualizarse estos datos. (semanal/mensual/estacional/anual, etc.). Además, se conocen las causas raíz y se pueden hacer estadísticas sobre ellas.', now()),
  ('mc-3.1-2', 'mi-3.1', 2, 'Developed', 'The tools and templates were created to help doing the data-analysis and trendlines.', 'Las herramientas y plantillas se crearon para ayudar en el análisis de datos y las líneas de tendencia.', now()),
  ('mc-3.1-3', 'mi-3.1', 3, 'Installed', 'Training was delivered how to do this data analysis and trendlines e.g. through a webinar to all H&S responsibles.', 'Se impartió formación sobre cómo realizar este análisis de datos y líneas de tendencia, por ejemplo, mediante un seminario web para todos los responsables de H&S.', now()),
  ('mc-3.1-4', 'mi-3.1', 4, 'Mastered', 'A process is in place to regularly review, do trendline analysis, setting up safety campaigns to continuously improve.', 'Existe un proceso para revisar regularmente, hacer análisis de tendencias y establecer campañas de seguridad para mejorar continuamente.', now()),
  ('mc-3.1-5', 'mi-3.1', 5, 'Sustained', 'Continuous improvement is reached and further analysis and trendlines indicate that the safety level is further increasing e.g. the shift from reporting more leading rather than lagging incidents /', 'Se logra una mejora continua y análisis y tendencias adicionales indican que el nivel de seguridad sigue aumentando, por ejemplo, el cambio de reportar incidentes más avanzados en lugar de rezagados /', now()),
  ('mc-3.2-1', 'mi-3.2', 1, 'Defined', 'The top 10-15 high risk events have been identified e.g. through data analysis from the Potential Serious near misses and other accidents at Puratos.', 'Los 10-15 eventos de alto riesgo principales han sido identificados, por ejemplo, mediante análisis de datos de los posibles accidentes graves y otros accidentes en Puratos.', now()),
  ('mc-3.2-2', 'mi-3.2', 2, 'Developed', 'A high risk event guide defining what could cause the high risk consequence, what are the preventive measures and what are the measures to reduce the consequence has been created, communicated and implemented.', 'Se ha creado, comunicado e implementado una guía de eventos de alto riesgo que define qué podría causar la consecuencia de alto riesgo, cuáles son las medidas preventivas y cuáles son las medidas para reducir las consecuencias.', now()),
  ('mc-3.2-3', 'mi-3.2', 3, 'Installed', 'People received training in how to use the high risk event guide and can recognize high risk activities in the guide in their work situation.', 'Las personas recibieron formación sobre cómo utilizar la guía de eventos de alto riesgo y pueden reconocer actividades de alto riesgo en la guía en su situación laboral.', now()),
  ('mc-3.2-4', 'mi-3.2', 4, 'Mastered', 'High risk activities are systematic recognized and controls in accordance with the High Risk Event Guide are systematic implemented.', 'Las actividades de alto riesgo se reconocen sistemáticamente y los controles de acuerdo con la Guía de Eventos de Alto Riesgo se implementan de forma sistemática.', now()),
  ('mc-3.2-5', 'mi-3.2', 5, 'Sustained', 'There is a process in place to regularly review, validate and modify the High Risk Event guide in accordance with the latest data.', 'Existe un proceso para revisar, validar y modificar periódicamente la guía de Eventos de Alto Riesgo de acuerdo con los datos más recientes.', now()),
  ('mc-3.3-1', 'mi-3.3', 1, 'Defined', 'The leading by example is defined by visible leadership, you visibly show the right behaviour, care for our people, company and have the right behaviours to do this.', 'El liderazgo con el ejemplo se define por un liderazgo visible, muestras el comportamiento adecuado, te preocupas por nuestra gente, la empresa y tienes los comportamientos adecuados para hacerlo.', now()),
  ('mc-3.3-2', 'mi-3.3', 2, 'Developed', 'The leadership manual has been created and defines what is expected for leaders, with guidelines, behaviours, etc.', 'Se ha creado el manual de liderazgo y define lo que se espera de los líderes, con directrices, comportamientos, etc.', now()),
  ('mc-3.3-3', 'mi-3.3', 3, 'Installed', 'Leadership received the manual and training about Leading by example.', 'El liderazgo recibió el manual y la formación sobre liderar con el ejemplo.', now()),
  ('mc-3.3-4', 'mi-3.3', 4, 'Mastered', 'KPI''s monitoring leading by example show that leaders are walking the talk. They are ambassadors for Health and Safety.', 'Los KPIs que supervisan con el ejemplo demuestran que los líderes predican. Son embajadores de la Salud y la Seguridad.', now()),
  ('mc-3.3-5', 'mi-3.3', 5, 'Sustained', 'Leading by example becomes a habit, a way of living, it becomes behavioural.', 'Liderar con el ejemplo se convierte en un hábito, una forma de vivir, se vuelve conductual.', now()),
  ('mc-3.4-1', 'mi-3.4', 1, 'Defined', 'Root cause analysis has been defined using the why tree method and part of the Reporting, incident notification and investigation procedure defined above.', 'El análisis de causa raíz se ha definido utilizando el método del árbol por qué y parte del procedimiento de Informe, notificación de incidentes e investigación descrito anteriormente.', now()),
  ('mc-3.4-2', 'mi-3.4', 2, 'Developed', 'The guidelines including templates on decision trees, flow charts, root cause alignment template were communicated and people were trained on how to best use it.', 'Se comunicaron las directrices, incluyendo plantillas sobre árboles de decisión, diagramas de flujo y plantilla de alineación de causas raíz, y se formó a la gente sobre cómo utilizarla mejor.', now()),
  ('mc-3.4-3', 'mi-3.4', 3, 'Installed', 'Investigations of all near misses are done and reports generated and placed in a central repository.', 'Se realizan investigaciones de todos los casi accidentes y se generan los informes que se almacenan en un repositorio central.', now()),
  ('mc-3.4-4', 'mi-3.4', 4, 'Mastered', 'Root causes are being used to define corrective actions and to avoid re-currence on the particular site.', 'Las causas raíz se están utilizando para definir acciones correctivas y evitar que se repitan en el sitio concreto.', now()),
  ('mc-3.4-5', 'mi-3.4', 5, 'Sustained', 'Re-currence of root causes is prevented due to improved awareness and sharing through e.g Safety Moments across the company (Group).', 'Se evita la recurrencia de las causas raíz gracias a una mayor concienciación y compartición a través de Momentos de Seguridad en toda la empresa (Grupo).', now()),
  ('mc-3.5-1', 'mi-3.5', 1, 'Defined', 'Root cause analysis has been defined using the why tree method and part of the Reporting, incident notification and investigation procedure defined above.', 'El análisis de causa raíz se ha definido utilizando el método del árbol por qué y parte del procedimiento de Informe, notificación de incidentes e investigación descrito anteriormente.', now()),
  ('mc-3.5-2', 'mi-3.5', 2, 'Developed', 'The guidelines including templates on decision trees, flow charts, root cause alignment template were communicated and people were trained on how to best use it.', 'Se comunicaron las directrices, incluyendo plantillas sobre árboles de decisión, diagramas de flujo y plantilla de alineación de causas raíz, y se formó a la gente sobre cómo utilizarla mejor.', now()),
  ('mc-3.5-3', 'mi-3.5', 3, 'Installed', 'Investigations of all significant/interesting observations are done and reports generated and placed in a central repository.', 'Se realizan investigaciones de todas las observaciones significativas o interesantes y se generan informes que se colocan en un repositorio central.', now()),
  ('mc-3.5-4', 'mi-3.5', 4, 'Mastered', 'Root causes are being used to define corrective actions and to avoid re-currence on the particular site.', 'Las causas raíz se están utilizando para definir acciones correctivas y evitar que se repitan en el sitio concreto.', now()),
  ('mc-3.5-5', 'mi-3.5', 5, 'Sustained', 'Re-currence of root causes is prevented due to improved awareness and sharing through e.g Safety Moments across the company (Group).', 'Se evita la recurrencia de las causas raíz gracias a una mayor concienciación y compartición a través de Momentos de Seguridad en toda la empresa (Grupo).', now()),
  ('mc-3.6-1', 'mi-3.6', 1, 'Defined', 'Safety in Design register is part of the RA procedure which is defined in accordance with the group procedure.', 'El registro de seguridad en el diseño forma parte del procedimiento de RA, que se define de acuerdo con el procedimiento de grupo.', now()),
  ('mc-3.6-2', 'mi-3.6', 2, 'Developed', 'Templates for Safety in design register has been developed and the use is understood by relevant personnel through training and on the job coaching. Also the safety in design procedure has been communicated to all staff.', 'Se han desarrollado plantillas para el registro de seguridad en el diseño y su uso es comprendido por el personal relevante mediante formación y formación en el trabajo. También se ha comunicado el procedimiento de seguridad en el diseño a todo el personal.', now()),
  ('mc-3.6-3', 'mi-3.6', 3, 'Installed', 'Rigorous and comprehensive Safety In Design register (analysis) are carried out to idenitfy hazards, risks and implement proper controls to mitigate the risks in the design development phase to an acceptable level.', 'Se realizan registros rigurosos y completos de Seguridad en el Diseño (análisis) para identificar peligros, riesgos e implementar controles adecuados que mitiguen los riesgos en la fase de desarrollo del diseño hasta un nivel aceptable.', now()),
  ('mc-3.6-4', 'mi-3.6', 4, 'Mastered', 'Controls are implemented in accordance with the Safety in Design register and keep the risks identified during the design development phase to an acceptable level.', 'Los controles se implementan de acuerdo con el registro de Seguridad en el Diseño y mantienen los riesgos identificados durante la fase de desarrollo del diseño en un nivel aceptable.', now()),
  ('mc-3.6-5', 'mi-3.6', 5, 'Sustained', 'A process is in place to regularly review, validate and modify the Safety in Design Risk register.', 'Existe un proceso para revisar, validar y modificar periódicamente el registro de Seguridad en el Riesgo de Diseño.', now()),
  ('mc-4.1-1', 'mi-4.1', 1, 'Defined', 'Good practices are defined in order to share them with others. Purpose is encouraging greater innovation and the need to challenge the status quo with a view to garnering better, more resilient results.', 'Las buenas prácticas se definen para compartirlas con otros. El propósito es fomentar una mayor innovación y la necesidad de desafiar el statu quo con el fin de obtener resultados mejores y más resilientes.', now()),
  ('mc-4.1-2', 'mi-4.1', 2, 'Developed', 'A central reporting system including template to share best practice (e.g. Safety Innovation)  has been developed and purpose is to be used to share good practices. There is no best practice, there are multiple good practices.', 'Se ha desarrollado un sistema central de informes que incluye plantillas para compartir buenas prácticas (por ejemplo, Innovación en Seguridad) y su objetivo es utilizarse para compartir buenas prácticas. No existe una buena práctica, existen múltiples buenas prácticas.', now()),
  ('mc-4.1-3', 'mi-4.1', 3, 'Installed', 'All employees have been trained in using the templates and looking for good innovation. The idea that people are the solution and can be harnessed, as opposed to people being the problem and needing to be told what to do.', 'Todos los empleados han sido formados para usar las plantillas y buscar buena innovación. La idea de que las personas son la solución y se pueden aprovechar, en lugar de que las personas sean el problema y necesiten que les digan qué hacer.', now()),
  ('mc-4.1-4', 'mi-4.1', 4, 'Mastered', 'Good practices, safety innovation documents are being created by people in our organisation and shared onto a central repository. The good practice of the month is highlighted and recognized/rewarded.', 'Personas de nuestra organización crean documentos de buenas prácticas y innovación en seguridad y se comparten en un repositorio central. Se destaca y se reconoce y premia la buena práctica del mes.', now()),
  ('mc-4.1-5', 'mi-4.1', 5, 'Sustained', 'Sharing of good practices results in plants with more innovation/efficiency and a better work environment.', 'El intercambio de buenas prácticas da lugar a plantas con más innovación/eficiencia y un mejor ambiente laboral.', now()),
  ('mc-4.2-1', 'mi-4.2', 1, 'Defined', 'A reward and recognition program has been defined in order to help drive continuous improvement, e.g. in helping up the leading KPI''s, make good behaviour visible.', 'Se ha definido un programa de recompensas y reconocimiento para ayudar a impulsar la mejora continua, por ejemplo, subiendo los KPIs líderes y haciendo visible el buen comportamiento.', now()),
  ('mc-4.2-2', 'mi-4.2', 2, 'Developed', 'A token, diplom, certificate, etc. has been created as a gift to the person that did the exceptional thing.', 'Se ha creado un testimonio, un diploma, un certificado, etc., como regalo para la persona que hizo lo excepcional.', now()),
  ('mc-4.2-3', 'mi-4.2', 3, 'Installed', 'People are made aware of the program and encouraged to participated to it.', 'Se informa a la gente sobre el programa y se anima a participar en él.', now()),
  ('mc-4.2-4', 'mi-4.2', 4, 'Mastered', 'Regularly, e.g. monthly celebrations are held with the winners of each month for the categories they were nominated in.', 'Regularmente, por ejemplo, se celebran celebraciones mensuales con los ganadores de cada mes en las categorías en las que fueron nominados.', now()),
  ('mc-4.2-5', 'mi-4.2', 5, 'Sustained', 'A more positive attitude including ownership, involvement and accountability is reached with committed colleagues towards safety.', 'Se alcanza una actitud más positiva, incluyendo la responsabilidad, la implicación y la rendición de cuentas, con compañeros comprometidos con la seguridad.', now()),
  ('mc-4.3-1', 'mi-4.3', 1, 'Defined', 'A modern idea box has been identified.', 'Se ha identificado una caja de ideas moderna.', now()),
  ('mc-4.3-2', 'mi-4.3', 2, 'Developed', 'The platform for handing in suggestions has been developed.', 'Se ha desarrollado la plataforma para entregar sugerencias.', now()),
  ('mc-4.3-3', 'mi-4.3', 3, 'Installed', 'All employees received communication regarding this suggestion box.', 'Todos los empleados recibieron comunicación respecto a este buzón de sugerencias.', now()),
  ('mc-4.3-4', 'mi-4.3', 4, 'Mastered', 'Suggestions for improvement are continuously handed in. Management is making public what the suggestions of the month were and what was done with it and encourage to continue submitting new suggestions.', 'Las sugerencias para mejorar se entregan continuamente. La dirección está haciendo públicos cuáles fueron las sugerencias del mes y qué se hizo con ellas, y anima a seguir enviando nuevas sugerencias.', now()),
  ('mc-4.3-5', 'mi-4.3', 5, 'Sustained', 'A more positive attitude including ownership, involvement and accountability is reached with committed colleagues towards safety.', 'Se alcanza una actitud más positiva, incluyendo la responsabilidad, la implicación y la rendición de cuentas, con compañeros comprometidos con la seguridad.', now()),
  ('mc-4.4-1', 'mi-4.4', 1, 'Defined', 'Pro-active innovation and change has been defined as a radical innovation with continuous incremental innovations and improvements. It is building upon what worked well, to grow into something better.', 'La innovación y el cambio proactivos se han definido como una innovación radical con innovaciones e mejoras incrementales continuas. Consiste en construir sobre lo que funcionó bien, para crecer hacia algo mejor.', now()),
  ('mc-4.4-2', 'mi-4.4', 2, 'Developed', 'The mindset to  nurture and harness the creative energy of our employees and help people grow by innovating in order to use safety as a competitive advantage.', 'La mentalidad de nutrir y aprovechar la energía creativa de nuestros empleados y ayudar a las personas a crecer innovando para utilizar la seguridad como ventaja competitiva.', now()),
  ('mc-4.4-3', 'mi-4.4', 3, 'Installed', 'A culture of innovation is installed and people are challenging the status quo by bringing on new suggestions to innovate.', 'Se instaura una cultura de innovación y la gente desafía el statu quo introduciendo nuevas sugerencias para innovar.', now()),
  ('mc-4.4-4', 'mi-4.4', 4, 'Mastered', 'Pro-active innovation and change is applied resulting in a safer, better ,more innovative work environment.', 'Se aplica la innovación y el cambio proactivos, resultando en un entorno laboral más seguro, mejor e innovador.', now()),
  ('mc-4.4-5', 'mi-4.4', 5, 'Sustained', 'No reactive measures are needed anymore since we change and innovate before reactive measures are necessary.', 'Ya no se necesitan medidas reactivas, ya que cambiamos e innovamos antes de que sean necesarias las medidas reactivas.', now()),
  ('mc-4.5-1', 'mi-4.5', 1, 'Defined', 'A culture of caring is defined in the Safety Charter and in our Bradley curve - interdependent stage.', 'Una cultura de cuidado está definida en la Carta de Seguridad y en nuestra etapa de curva de Bradley - interdependiente.', now()),
  ('mc-4.5-2', 'mi-4.5', 2, 'Developed', 'Some guidelines are given what the Culture of Caring stands for. How we care - for example: be  vigilant, attentive / Look after each other  / actively intervene  /We commend safe and healthy behaviour and talk about it.', 'Se dan algunas pautas sobre lo que representa la Cultura del Cuidado. Cómo cuidamos - por ejemplo: estar vigilantes, atentos / cuidarnos unos a otros / intervenir activamente / Recomendamos conductas seguras y saludables y hablamos sobre ello.', now()),
  ('mc-4.5-3', 'mi-4.5', 3, 'Installed', 'Communication and training given regarding how our Culture of Caring is working, including well-being.', 'Se ofrece comunicación y formación sobre cómo funciona nuestra Cultura de Cuidado, incluyendo el bienestar.', now()),
  ('mc-4.5-4', 'mi-4.5', 4, 'Mastered', 'We care about our people and this is shown in everything we say / do .', 'Nos importan nuestras personas y esto se refleja en todo lo que decimos o hacemos.', now()),
  ('mc-4.5-5', 'mi-4.5', 5, 'Sustained', 'The culture of caring is embedded in our behaviour.', 'La cultura del cuidado está arraigada en nuestro comportamiento.', now());
