-- Madurez OpX — "OpX Maturity Pyramid" (framework Puratos, pilar Health and
-- Safety). MaturityItem/MaturityCriterio son datos de referencia sembrados
-- una sola vez desde la planilla fuente al final de este archivo.

CREATE TYPE "MaturityEvalTipo" AS ENUM ('AS_IS', 'TO_BE');

CREATE TABLE IF NOT EXISTS "MaturityItem" (
  "id"         TEXT NOT NULL,
  "codigo"     TEXT NOT NULL,
  "titulo"     TEXT NOT NULL,
  "workstream" TEXT NOT NULL,
  "nivel"      INTEGER NOT NULL,
  "orden"      INTEGER NOT NULL,
  "frecuencia" TEXT,
  "createdAt"  TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt"  TIMESTAMP(3) NOT NULL,
  CONSTRAINT "MaturityItem_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "MaturityItem_codigo_key" ON "MaturityItem"("codigo");
CREATE INDEX "MaturityItem_nivel_idx" ON "MaturityItem"("nivel");

CREATE TABLE IF NOT EXISTS "MaturityCriterio" (
  "id"         TEXT NOT NULL,
  "itemId"     TEXT NOT NULL,
  "paso"       INTEGER NOT NULL,
  "nombrePaso" TEXT NOT NULL,
  "textoEn"    TEXT NOT NULL,
  "textoEs"    TEXT NOT NULL,
  "createdAt"  TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "MaturityCriterio_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "MaturityCriterio_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "MaturityItem"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "MaturityCriterio_itemId_paso_key" ON "MaturityCriterio"("itemId", "paso");

CREATE TABLE IF NOT EXISTS "MaturityEvaluacion" (
  "id"         TEXT NOT NULL,
  "tipo"       "MaturityEvalTipo" NOT NULL DEFAULT 'AS_IS',
  "fecha"      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "planta"     TEXT,
  "evaluador"  TEXT,
  "comentario" TEXT,
  "createdBy"  TEXT,
  "createdAt"  TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt"  TIMESTAMP(3) NOT NULL,
  CONSTRAINT "MaturityEvaluacion_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "MaturityEvaluacion_tipo_fecha_idx" ON "MaturityEvaluacion"("tipo", "fecha");

CREATE TABLE IF NOT EXISTS "MaturityRespuesta" (
  "id"            TEXT NOT NULL,
  "evaluacionId"  TEXT NOT NULL,
  "criterioId"    TEXT NOT NULL,
  "itemId"        TEXT NOT NULL,
  "valor"         DOUBLE PRECISION,
  "observaciones" TEXT,
  "updatedBy"     TEXT,
  "createdAt"     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt"     TIMESTAMP(3) NOT NULL,
  CONSTRAINT "MaturityRespuesta_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "MaturityRespuesta_evaluacionId_fkey" FOREIGN KEY ("evaluacionId") REFERENCES "MaturityEvaluacion"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "MaturityRespuesta_criterioId_fkey" FOREIGN KEY ("criterioId") REFERENCES "MaturityCriterio"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "MaturityRespuesta_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "MaturityItem"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "MaturityRespuesta_evaluacionId_criterioId_key" ON "MaturityRespuesta"("evaluacionId", "criterioId");
CREATE INDEX "MaturityRespuesta_evaluacionId_idx" ON "MaturityRespuesta"("evaluacionId");

-- Datos de referencia del framework "OpX Maturity Pyramid - Health and Safety" (Puratos):
-- 24 items (MaturityItem) agrupados en 4 niveles x 5 workstreams, con 5 criterios
-- de madurez cada uno (MaturityCriterio) -- Defined/Developed/Installed/Mastered/Sustained.
-- Texto bilingue EN/ES extraido directamente de la planilla fuente
-- "OpX_HS_0.0_TEMP_01_Maturity_Pyramid_Health_Safety" entregada por el usuario.


